// ═══════════════════════════════════════════════════════════════════════════
// NativeBridge v2.1 — Unified API for Web + Native (Capacitor)
// Auto-generated by native_bridge.py
// ═══════════════════════════════════════════════════════════════════════════
const NativeBridge = {
    isNative: () => typeof window.Capacitor !== 'undefined' && window.Capacitor.isNativePlatform(),
    platform: () => typeof window.Capacitor !== 'undefined' ? window.Capacitor.getPlatform() : 'web',
    
    // ═══════════════════════════════════════════════════════════════════════
    // CAMERA — Capture photos (patient IDs, medical records)
    // ═══════════════════════════════════════════════════════════════════════
    async captureImage(targetId, quality = 90) {
        if (this.isNative()) {
            try {
                const { Camera } = window.Capacitor.Plugins;
                const image = await Camera.getPhoto({
                    quality: quality,
                    allowEditing: false,
                    resultType: 'Base64',
                    source: 'PROMPT'  // Camera or Gallery
                });
                const el = document.getElementById(targetId);
                if (el) {
                    el.src = 'data:image/jpeg;base64,' + image.base64String;
                    el.dataset.base64 = image.base64String;
                }
                return { success: true, base64: image.base64String };
            } catch (e) {
                console.error('[NativeBridge] Camera error:', e);
                return { success: false, error: e.message };
            }
        } else {
            // Web fallback: trigger hidden file input
            return new Promise((resolve) => {
                const input = document.createElement('input');
                input.type = 'file'; input.accept = 'image/*'; input.capture = 'environment';
                input.onchange = async (e) => {
                    const file = e.target.files[0];
                    if (!file) { resolve({ success: false, error: 'No file' }); return; }
                    const reader = new FileReader();
                    reader.onload = () => {
                        const el = document.getElementById(targetId);
                        if (el) { el.src = reader.result; el.dataset.base64 = reader.result.split(',')[1]; }
                        resolve({ success: true, base64: reader.result.split(',')[1] });
                    };
                    reader.readAsDataURL(file);
                };
                input.click();
            });
        }
    },
    
    // ═══════════════════════════════════════════════════════════════════════
    // FILE SYSTEM — Save files locally (medical reports, exports)
    // ═══════════════════════════════════════════════════════════════════════
    async saveFile(filename, base64Data, mimeType = 'application/octet-stream') {
        if (this.isNative()) {
            try {
                const { Filesystem, Directory, Encoding } = window.Capacitor.Plugins;
                await Filesystem.writeFile({
                    path: filename,
                    data: base64Data,
                    directory: Directory.Documents,
                    encoding: Encoding.Base64,
                });
                return { success: true, path: filename };
            } catch (e) {
                console.error('[NativeBridge] Filesystem error:', e);
                return { success: false, error: e.message };
            }
        } else {
            // Web fallback: download via Blob
            const blob = new Blob([atob(base64Data)], { type: mimeType });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url; a.download = filename; a.click();
            URL.revokeObjectURL(url);
            return { success: true, path: 'download' };
        }
    },
    
    // ═══════════════════════════════════════════════════════════════════════
    // BIOMETRICS — Secure admin authentication
    // ═══════════════════════════════════════════════════════════════════════
    async authenticateAdmin() {
        if (this.isNative()) {
            try {
                // Try Capacitor BiometricAuth plugin
                const { BiometricAuth } = window.Capacitor.Plugins || {};
                if (BiometricAuth) {
                    const result = await BiometricAuth.check();
                    if (result.available) {
                        const auth = await BiometricAuth.authenticate({
                            reason: 'Admin authentication required',
                            title: 'Hospital Admin',
                            subtitle: 'Please verify your identity',
                        });
                        return { success: true, verified: true };
                    }
                }
                // Fallback: PIN-based auth
                return this._pinAuth();
            } catch (e) {
                return this._pinAuth();
            }
        } else {
            return this._pinAuth();
        }
    },
    
    _pinAuth() {
        return new Promise((resolve) => {
            const pin = prompt('Enter Admin PIN:');
            resolve({ success: !!pin, verified: !!pin, method: 'pin' });
        });
    },
    
    // ═══════════════════════════════════════════════════════════════════════
    // DEVICE INFO — Get device metadata
    // ═══════════════════════════════════════════════════════════════════════
    async getDeviceInfo() {
        if (this.isNative()) {
            try {
                const { Device } = window.Capacitor.Plugins;
                const info = await Device.getInfo();
                return {
                    platform: info.platform,
                    model: info.model,
                    osVersion: info.osVersion,
                    manufacturer: info.manufacturer,
                };
            } catch (e) {
                return { platform: 'unknown', error: e.message };
            }
        } else {
            return {
                platform: 'web',
                model: navigator.userAgent,
                osVersion: 'n/a',
                manufacturer: 'n/a',
            };
        }
    },
    
    // ═══════════════════════════════════════════════════════════════════════
    // HAPTICS — Vibration feedback
    // ═══════════════════════════════════════════════════════════════════════
    async haptic(style = 'light') {
        if (this.isNative()) {
            try {
                const { Haptics, ImpactStyle } = window.Capacitor.Plugins;
                const impactMap = { light: ImpactStyle.Light, medium: ImpactStyle.Medium, heavy: ImpactStyle.Heavy };
                await Haptics.impact({ style: impactMap[style] || ImpactStyle.Light });
            } catch (e) { /* silent fail */ }
        } else if (navigator.vibrate) {
            navigator.vibrate(style === 'heavy' ? 50 : 20);
        }
    },
    
    // ═══════════════════════════════════════════════════════════════════════
    // SHARE — Native share sheet
    // ═══════════════════════════════════════════════════════════════════════
    async share(title, text, url) {
        if (this.isNative()) {
            try {
                const { Share } = window.Capacitor.Plugins;
                await Share.share({ title, text, url, dialogTitle: title });
                return { success: true };
            } catch (e) {
                return { success: false, error: e.message };
            }
        } else if (navigator.share) {
            try {
                await navigator.share({ title, text, url });
                return { success: true };
            } catch (e) {
                return { success: false, error: e.message };
            }
        } else {
            // Fallback: copy to clipboard
            const fullText = title + ': ' + text + (url ? ' ' + url : '');
            try {
                await navigator.clipboard.writeText(fullText);
                return { success: true, method: 'clipboard' };
            } catch (e) {
                return { success: false, error: 'Share not available' };
            }
        }
    },
    
    // ═══════════════════════════════════════════════════════════════════════
    // LOCAL NOTIFICATIONS
    // ═══════════════════════════════════════════════════════════════════════
    async notify(title, body, scheduleAt = null) {
        if (this.isNative() && scheduleAt) {
            try {
                const { LocalNotifications } = window.Capacitor.Plugins;
                await LocalNotifications.schedule({
                    notifications: [{
                        title: title, body: body,
                        id: Date.now(),
                        schedule: { at: new Date(scheduleAt) },
                    }]
                });
                return { success: true };
            } catch (e) { return { success: false, error: e.message }; }
        } else if ('Notification' in window) {
            try {
                if (Notification.permission === 'granted') {
                    new Notification(title, { body });
                } else if (Notification.permission !== 'denied') {
                    const perm = await Notification.requestPermission();
                    if (perm === 'granted') new Notification(title, { body });
                }
                return { success: true };
            } catch (e) { return { success: false, error: e.message }; }
        }
        return { success: false, error: 'Notifications not available' };
    },
};

// Export for module systems
if (typeof module !== 'undefined' && module.exports) module.exports = NativeBridge;
